//! A private RAG assistant: documents chunked and embedded into Qdrant,
//! answers generated by Ollama on the company's own GPU server, and Claude
//! Code reaching the same knowledge from outside through an MCP server.

use super::*;

pub fn rag() -> System {
    use EdgeStyle::*;
    let mut layers = standard_layers();
    layers.insert(3, layer("ai", "AI & retrieval", 0x14b8a6));
    System {
        name: "Atlas Knowledge".into(),
        tagline: "Private RAG on Ollama, Qdrant for vectors, Claude Code from outside".into(),
        overview: "Engineers ask questions about the company's code, runbooks and documents. \
                   Sources are chunked, embedded with a local Ollama model and stored in \
                   Qdrant. A question is embedded the same way, the closest chunks are \
                   re-ranked and given to a local model, so nothing leaves the company's \
                   servers. Developers also reach the same search from Claude Code through an \
                   MCP server; only the snippets they choose go to Claude."
            .into(),
        provider: Provider::Hetzner,
        layers,
        nodes: vec![
            node(
                "chat",
                "Chat app",
                "web-client",
                Some("nextjs"),
                "clients",
                "Answers with the sources they came from.",
            )
            .device()
            .slot(0.),
            node(
                "claude-code",
                "Claude Code",
                "agent",
                Some("claude-code"),
                "clients",
                "Developers' coding agent, outside the company network.",
            )
            .slot(1.),
            node(
                "slack",
                "Slack bot",
                "external",
                None,
                "clients",
                "/ask in any channel.",
            )
            .slot(2.),
            node(
                "proxy",
                "Reverse proxy",
                "load-balancer",
                Some("traefik"),
                "edge",
                "TLS, SSO, rate limits per user.",
            )
            .container()
            .slot(0.),
            node(
                "sso",
                "Single sign-on",
                "auth",
                Some("keycloak"),
                "edge",
                "Groups decide which collections a user can search.",
            )
            .container()
            .slot(1.),
            node(
                "api",
                "RAG API",
                "service",
                Some("python"),
                "services",
                "Retrieval, prompt building, streaming answers.",
            )
            .pods(3)
            .items(&["Retriever", "Prompt builder", "SSE streaming"])
            .slot(0.),
            node(
                "mcp",
                "MCP server",
                "service",
                Some("rust"),
                "services",
                "search_docs and read_doc tools for Claude Code, scoped by token.",
            )
            .pods(2)
            .slot(1.),
            node(
                "ingest",
                "Ingestion workers",
                "worker",
                Some("python"),
                "services",
                "Fetch, split into ~800-token chunks, embed, upsert.",
            )
            .pods(4)
            .items(&["Fetchers", "Chunker", "Embed + upsert"])
            .slot(2.),
            node(
                "jobs",
                "Ingestion queue",
                "queue",
                Some("rabbitmq"),
                "async",
                "One job per changed document.",
            )
            .container()
            .slot(1.),
            node(
                "embed",
                "Embeddings",
                "llm",
                Some("ollama"),
                "ai",
                "nomic-embed-text on the GPU server.",
            )
            .vm()
            .slot(0.),
            node(
                "llm",
                "Local LLM",
                "llm",
                Some("ollama"),
                "ai",
                "A 32B instruct model, 4-bit, on two GPUs.",
            )
            .vm()
            .slot(1.),
            node(
                "rerank",
                "Re-ranker",
                "ml",
                Some("python"),
                "ai",
                "Cross-encoder: keeps the best 8 of 40 hits.",
            )
            .pods(1)
            .slot(2.),
            node(
                "claude",
                "Claude API",
                "llm",
                Some("claude"),
                "ai",
                "Used only by Claude Code, outside our servers.",
            )
            .managed()
            .slot(3.),
            node(
                "vectors",
                "Vector DB",
                "vector-db",
                Some("qdrant"),
                "data",
                "One collection per access group; HNSW, cosine.",
            )
            .db("vectors")
            .container()
            .slot(0.),
            node(
                "meta",
                "Metadata DB",
                "sql-db",
                Some("postgresql"),
                "data",
                "Documents, chunks, conversations, feedback.",
            )
            .db("meta")
            .container()
            .slot(1.),
            node(
                "files",
                "Source files",
                "object-storage",
                Some("minio"),
                "data",
                "Original PDFs and exports.",
            )
            .managed()
            .slot(2.),
            node(
                "gpu",
                "GPU server",
                "vm",
                Some("hetzner"),
                "platform",
                "Dedicated GEX server running Ollama.",
            )
            .vm()
            .slot(0.),
            node(
                "k3s",
                "k3s cluster",
                "cluster",
                Some("kubernetes"),
                "platform",
                "Three Cloud Servers for the services.",
            )
            .managed()
            .slot(1.),
            node(
                "metrics",
                "Metrics",
                "monitoring",
                Some("prometheus"),
                "platform",
                "Tokens per second, retrieval hit rate, answer feedback.",
            )
            .container()
            .slot(2.),
        ],
        edges: vec![
            edge("chat", "proxy", Request, Some("HTTPS")),
            edge("slack", "proxy", Request, Some("webhook")),
            edge("claude-code", "mcp", Request, Some("MCP over HTTPS")),
            edge("proxy", "sso", Request, Some("OIDC")),
            edge("proxy", "api", Request, None),
            edge("api", "chat", Socket, Some("SSE tokens")),
            edge("api", "embed", Rpc, Some("embed question")),
            edge("api", "vectors", Rpc, Some("top 40")),
            edge("api", "rerank", Rpc, None),
            edge("api", "llm", Rpc, Some("generate")),
            edge("api", "meta", Request, Some("SQL")),
            edge("mcp", "vectors", Rpc, Some("search")),
            edge("mcp", "embed", Rpc, None),
            edge("claude-code", "claude", Request, Some("chosen snippets")),
            edge("files", "jobs", Async, Some("object created")),
            edge("jobs", "ingest", Async, None),
            edge("ingest", "embed", Rpc, Some("embed chunks")),
            edge("ingest", "vectors", Request, Some("upsert")),
            edge("ingest", "meta", Request, None),
            edge("embed", "gpu", Rpc, None),
            edge("llm", "gpu", Rpc, None),
        ],
        concepts: strings(&[
            "Retrieval-augmented generation",
            "Chunking and overlap",
            "Embeddings",
            "Approximate nearest neighbours (HNSW)",
            "Re-ranking",
            "Model Context Protocol",
            "Access control on retrieval",
        ]),
        functional: strings(&[
            "Ask questions in chat or Slack and get answers with their sources",
            "Search only what you are allowed to read",
            "New and changed documents searchable within 5 minutes",
            "Developers search the same knowledge from Claude Code",
            "Thumbs up / down on answers to improve retrieval",
        ]),
        non_functional: strings(&[
            "Documents and questions never leave our servers (except what a developer sends to Claude)",
            "First token in under 1.5 s, whole answer in under 10 s",
            "Retrieval recall@8 above 0.85 on the evaluation set",
            "Works with the GPU server down: search still answers, generation queues",
        ]),
        apis: vec![
            api(
                "POST",
                "/v1/ask",
                "api",
                "Question in, answer streamed with sources.",
            ),
            api(
                "GET",
                "/v1/conversations/{id}",
                "api",
                "History of a conversation.",
            ),
            api("POST", "/v1/feedback", "api", "Rate an answer."),
            api(
                "POST",
                "/v1/sources/{id}/reindex",
                "ingest",
                "Re-embed one source.",
            ),
            api(
                "POST",
                "/mcp",
                "mcp",
                "MCP tools: search_docs(query, limit), read_doc(id).",
            ),
        ],
        sockets: vec![socket(
            "GET /v1/ask/stream (SSE)",
            "api",
            "server → client",
            "Tokens as they are generated, then the source list.",
        )],
        databases: vec![
            Database {
                id: "meta".into(),
                name: "Metadata DB".into(),
                tables: vec![
                    table(
                        "documents",
                        "One per source file or page",
                        &[
                            ("id", "uuid", "pk"),
                            ("source", "text", ""),
                            ("uri", "text", ""),
                            ("access_group", "text", ""),
                            ("sha256", "char(64)", ""),
                            ("indexed_at", "timestamptz", "null"),
                        ],
                    ),
                    table(
                        "chunks",
                        "Text given to the model; vectors live in Qdrant",
                        &[
                            ("id", "uuid", "pk"),
                            ("document_id", "uuid", "fk:documents.id"),
                            ("ord", "int", ""),
                            ("text", "text", ""),
                            ("tokens", "int", ""),
                        ],
                    ),
                    table(
                        "conversations",
                        "",
                        &[
                            ("id", "uuid", "pk"),
                            ("user_id", "text", ""),
                            ("started_at", "timestamptz", ""),
                        ],
                    ),
                    table(
                        "messages",
                        "",
                        &[
                            ("id", "uuid", "pk"),
                            ("conversation_id", "uuid", "fk:conversations.id"),
                            ("role", "text", ""),
                            ("content", "text", ""),
                            ("chunk_ids", "uuid[]", "null"),
                            ("rating", "smallint", "null"),
                        ],
                    ),
                ],
            },
            Database {
                id: "vectors".into(),
                name: "Vector DB (Qdrant)".into(),
                tables: vec![table(
                    "docs_<group>",
                    "One collection per access group",
                    &[
                        ("id", "uuid", "pk"),
                        ("vector", "float[768]", ""),
                        ("chunk_id", "uuid", "fk:chunks.id"),
                        ("document_id", "uuid", ""),
                        ("updated_at", "datetime", ""),
                    ],
                )],
            },
        ],
        flows: vec![
            flow(
                "Answer a question",
                "From the question to streamed tokens.",
                &[
                    ("chat", "proxy", "The user asks; SSO adds their groups."),
                    ("api", "embed", "The question is embedded locally."),
                    (
                        "api",
                        "vectors",
                        "Qdrant returns the 40 nearest chunks in the user's collections.",
                    ),
                    ("api", "rerank", "The re-ranker keeps the best 8."),
                    (
                        "api",
                        "llm",
                        "The prompt (question + chunks) goes to the local model.",
                    ),
                    (
                        "api",
                        "chat",
                        "Tokens stream back over SSE, then the sources.",
                    ),
                ],
            ),
            flow(
                "Index a document",
                "A PDF uploaded to the knowledge bucket.",
                &[
                    (
                        "files",
                        "jobs",
                        "The bucket publishes an object-created event.",
                    ),
                    ("jobs", "ingest", "A worker takes the job."),
                    ("ingest", "embed", "Text is split and each chunk embedded."),
                    (
                        "ingest",
                        "vectors",
                        "Vectors are upserted; old ones of the document removed.",
                    ),
                ],
            ),
            flow(
                "Claude Code looks something up",
                "The developer's agent uses our search.",
                &[
                    (
                        "claude-code",
                        "mcp",
                        "Claude Code calls search_docs with the developer's token.",
                    ),
                    (
                        "mcp",
                        "vectors",
                        "Only collections the token allows are searched.",
                    ),
                    (
                        "claude-code",
                        "claude",
                        "The agent sends the snippets it needs to Claude.",
                    ),
                ],
            ),
        ],
        reliability: vec![
            note(
                "GPU server down",
                "Search keeps working (embeddings fall back to CPU); generation requests wait in a queue and the UI says so.",
            ),
            note(
                "Stale answers",
                "Each chunk carries its document hash; re-ingest replaces vectors atomically per document.",
            ),
            note(
                "Prompt injection",
                "Retrieved text is quoted as data; tools are read-only; the MCP server only exposes search and read.",
            ),
            note(
                "Evaluation",
                "A fixed question set runs nightly; recall and answer ratings are graphed in Grafana.",
            ),
        ],
        cluster: Some(Cluster {
            context: None,
            namespace: "atlas".into(),
        }),
        custom_techs: Vec::new(),
    }
}
